mapper.sql:
SELECT u.id, u.username, u.nickname, u.avatar_url AS avatar, CASE WHEN SUM(CASE WHEN r.role_code = 'MERCHANT' THEN 1 ELSE 0 END) > 0 THEN 'MERCHANT' ELSE 'STUDENT' END AS userRole, u.status, u.created_at AS createdAt FROM sys_user u INNER JOIN sys_user_role ur ON ur.user_id = u.id INNER JOIN sys_role r ON r.id = ur.role_id WHERE r.role_code IN ('STUDENT', 'MERCHANT')
AND u.status = #{status}
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )
GROUP BY u.id, u.username, u.nickname, u.avatar_url, u.status, u.created_at
HAVING userRole = #{role}

