SELECT m.id AS merchantId, m.user_id AS userId, m.name AS merchantName, m.stall_id AS stallId, s.name AS stallName, c.id AS canteenId, c.name AS canteenName, c.type AS canteenType, m.description, m.apply_status AS applyStatus, m.reject_reason AS rejectReason, m.created_at AS createdAt FROM merchant m LEFT JOIN stall s ON s.id = m.stall_id LEFT JOIN canteen c ON c.id = s.canteen_id WHERE 1 = 1
AND m.apply_status = #{applyStatus}
ORDER BY m.created_at DESC, m.id DESC LIMIT #{offset}, #{size}

mapper.sql:
SELECT r.id, r.user_id AS userId, CASE WHEN r.is_anonymous = 1 THEN '匿名用户' ELSE su.nickname END AS userNickname, CASE WHEN r.is_anonymous = 1 THEN NULL ELSE su.avatar_url END AS userAvatar, r.target_type AS targetType, r.dish_id AS targetId, r.dish_id AS dishId, d.name AS dishName, m.name AS merchantName, r.overall_score AS overallScore, r.content, r.is_anonymous AS isAnonymous, r.like_count AS likeCount, r.status, r.created_at AS createdAt FROM review r INNER JOIN sys_user su ON su.id = r.user_id INNER JOIN dish d ON d.id = r.dish_id INNER JOIN merchant m ON m.id = d.merchant_id WHERE 1 = 1
AND r.target_type = #{targetType}
AND r.status = #{status}
AND ( r.content LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%') OR su.nickname LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') )

