mapper.sql:
SELECT d.id, d.merchant_id AS merchantId, m.name AS merchantName, d.canteen_id AS canteenId, c.name AS canteenName, d.stall_id AS stallId, s.name AS stallName, d.category_id AS categoryId, cg.name AS categoryName, d.name, d.price, d.cover_image_url AS coverImageUrl, d.average_score AS averageScore, d.status, d.is_join_lottery AS isJoinLottery, d.view_count AS viewCount, d.favorite_count AS favoriteCount, d.review_count AS reviewCount, d.created_at AS createdAt FROM dish d INNER JOIN merchant m ON m.id = d.merchant_id INNER JOIN canteen c ON c.id = d.canteen_id INNER JOIN stall s ON s.id = d.stall_id LEFT JOIN category cg ON cg.id = d.category_id WHERE 1 = 1
AND d.merchant_id = #{merchantId}
AND d.canteen_id = #{canteenId}
AND d.stall_id = #{stallId}
AND d.status = #{status}
AND ( d.name LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%') OR c.name LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%') OR cg.name LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT COUNT(1)
FROM (

) dish_list

SELECT
    dates.activity_date AS date,
    COALESCE(activity.activeUsers, 0) AS activeUsers,
    COALESCE(lottery.lotteryCount, 0) AS lotteryCount,
    COALESCE(review.reviewCount, 0) AS reviewCount
FROM (
    SELECT DATE(occurred_at) AS activity_date
    FROM user_activity_log
    WHERE occurred_at >= #{startTime}
      AND occurred_at < #{endTime}
    UNION
    SELECT DATE(created_at) AS activity_date
    FROM lottery_record
    WHERE created_at >= #{startTime}
      AND created_at < #{endTime}
    UNION
    SELECT DATE(created_at) AS activity_date
    FROM review
    WHERE created_at >= #{startTime}
      AND created_at < #{endTime}
) dates
LEFT JOIN (
    SELECT
        DATE(occurred_at) AS activity_date,
        COUNT(DISTINCT user_id) AS activeUsers
    FROM user_activity_log
    WHERE occurred_at >= #{startTime}
      AND occurred_at < #{endTime}
    GROUP BY DATE(occurred_at)
) activity ON activity.activity_date = dates.activity_date
LEFT JOIN (
    SELECT
        DATE(created_at) AS activity_date,
        COUNT(1) AS lotteryCount
    FROM lottery_record
    WHERE created_at >= #{startTime}
      AND created_at < #{endTime}
    GROUP BY DATE(created_at)
) lottery ON lottery.activity_date = dates.activity_date
LEFT JOIN (
    SELECT
        DATE(created_at) AS activity_date,
        COUNT(1) AS reviewCount
    FROM review
    WHERE created_at >= #{startTime}
      AND created_at < #{endTime}
      AND status != 'DELETED'
    GROUP BY DATE(created_at)
) review ON review.activity_date = dates.activity_date
ORDER BY dates.activity_date ASC
